package com.hs.listing.model; import com.hs.listing.model.constant.ListingEnums.*; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Table(name="listing_commercial_details") @Getter @Setter @NoArgsConstructor public class ListingCommercialDetail { @Id private String listingId; @MapsId @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="listing_id") private Listing listing; @Enumerated(EnumType.STRING) @Column(name="position_type",nullable=false) private PositionType positionType; @Column(name="frontage_width_m") private BigDecimal frontageWidthM; @Column(name="length_m") private BigDecimal lengthM; @Column(name="road_width_m") private BigDecimal roadWidthM; @Column(name="frontage_count") private Integer frontageCount; @Column(name="rented_floor_count") private Integer rentedFloorCount; @Column(name="has_mezzanine") private Boolean hasMezzanine; @Column(name="restroom_count") private Integer restroomCount; @Column(name="access_type") private String accessType; @Enumerated(EnumType.STRING) @Column(name="parking_type") private ParkingType parkingType; @Column(name="handover_status",nullable=false) private String handoverStatus; @Column(name="has_three_phase_power") private Boolean hasThreePhasePower; @Column(name="has_standard_fire_safety") private Boolean hasStandardFireSafety; @Column(name="operating_hours_description") private String operatingHoursDescription; @Column(name="restricted_businesses") private String restrictedBusinesses; @Column(name="loading_area_description") private String loadingAreaDescription; }
